33: STDLL stata_call(int argc, char *argv[])
34: {
35: 
36: 	int m,n;
37: 	ST_int row, col;
38: 	//check correct number and type of args
39: 	ST_double *c;//[n];   //arg0
40: 	ST_double *H;//[n*n]; //arg1
41: 	ST_double *A;//[n];  //arg2
42: 	ST_double *b;//[1]; //arg3
43: 	ST_double *l;//[n]; //arg4
44: 	ST_double *u;//[n]; //arg5
45: 	ST_double *dbound;	int bound; //arg6
46: 	ST_double *margin; //arg7
47: 	ST_double *dmaxiter; int maxiter; //arg8
48: 	ST_double *sigf; //arg9
49: 	int retVal;
50: 
51: 	double *primal;//[3*38]; //result (vector of W weights)
52: 	double *dual;//[1+(2*38)]; //result that gets ignored (dual solution)
53: 
54: 	int loqo_return;
55: 	int i;
56: 
57: 	ALLOC_AND_READ_FROM_STATA(argv[1],H,row,col,retVal);	//read in H matrix
58: 	//sanity check on H
59: 	n=col;
60: 	if (n != row)
61: 	{
62: 		SF_error("H matrix is not symmetric\n");
63: 		return ERROR_H_NOT_SYMMETRIC;
64: 	}
65: 
66: 	ALLOC_AND_READ_FROM_STATA(argv[0],c,row,col,retVal);	//read in c vector
67: 	if (n != row)
68: 	{
69: 		SF_error("H and c are incompatible\n");
70: 		return ERROR_H_C_INCOMPATIBLE;
71: 	//second dimension of c not checked
72: 	}
73: 
74: 	ALLOC_AND_READ_FROM_STATA(argv[2],A,row,col,retVal);	//read in A vector
75: 	m=row;
76: 	if (n != col)
77: 	{
78: 		SF_error("A is incompatible with H & c\n");
79: 		return ERROR_H_A_INCOMPATIBLE;
80: 	}
81: 
82: 	ALLOC_AND_READ_FROM_STATA(argv[3],b,row,col,retVal);	//read in b value
83: 	if (m != (row * col))
84: 	{
85: 		SF_error("b is incompatible with A & c\n");
86: 		return ERROR_A_b_INCOMPATIBLE;
87: 	}
88: 
89: 	ALLOC_AND_READ_FROM_STATA(argv[4],l,row,col,retVal);	//read in l vector
90: 	if (n != (row * col))
91: 	{
92: 		SF_error("l is incompatible with H & c & A");
93: 		return ERROR_H_l_INCOMPATIBLE;
94: 	}
95: 
96: 	ALLOC_AND_READ_FROM_STATA(argv[5],u,row,col,retVal);	//read in u vector
97: 	if (n != (row * col))
98: 	{
99: 		SF_error("u is incompatible with H & c & A & l");
100: 		return ERROR_H_u_INCOMPATIBLE;
101: 	}
102: 	ALLOC_AND_READ_FROM_STATA(argv[6],dbound,row,col,retVal); bound = (int) *dbound;	//read in bound value
103: 	if (1 != (row * col))
104: 	{
105: 		SF_error("bound should be a 1x1 matrix and an integer value");
106: 		return ERROR_BOUND_SCALAR;
107: 	}
108: 	ALLOC_AND_READ_FROM_STATA(argv[7],margin,row,col,retVal);	//read in margin value
109: 	if (1 != (row * col))
110: 	{
111: 		SF_error("margin should be a 1x1 matrix");
112: 		return ERROR_MARGIN_SCALAR;
113: 	}
114: 
115: 	ALLOC_AND_READ_FROM_STATA(argv[8],dmaxiter,row,col,retVal); maxiter = (int)*dmaxiter;//read in maxiter value
116: 	if (1 != (row * col))
117: 	{
118: 		SF_error("dmaxiter should be a 1x1 matrix and an integer value");
119: 		return ERROR_MAXITER_SCALAR;
120: 	}
121: 	ALLOC_AND_READ_FROM_STATA(argv[9],sigf,row,col,retVal);//read in sigf value
122: 	if (1 != (row * col))
123: 	{
124: 		SF_error("sigf should be a 1x1 matrix");
125: 		return ERROR_SIGF_SCALAR;
126: 	}
127: 
128: 	row = SF_row(argv[10]);
129: 	if (row != n)
130: 	{
131: 		SF_error("solution matrix is incompatible with H");
132: 		return ERROR_SIGF_SCALAR;
133: 	}
134: 	
135: 	primal = calloc(n * 3, sizeof(ST_double));
136: 	dual = calloc(m + (n * 2), sizeof(ST_double));
137: 
138: 	SF_display("starting quadratic optimization\n");
139: 	loqo_return = pr_loqo(n,m,c,H,A,b,l,u,primal,dual,2,*sigf,maxiter,*margin,bound,0);
140: 
141: 
142: 	//output to wsol
143: 	SF_display("saving matrix\n");
144: 	for(i=0;i<n;i++) 
145: 	{
146: 		SF_mat_store(argv[10],i+1,1,primal[i]);
147: 	}
148: 	SF_display("done\n");
149: 
150: 	return(0) ;
151: 
152: }
